import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as s,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何從 Linux 命令列安裝軟件 | LCTT x X-CMD","titleTemplate":false,"description":"如何從 Linux 命令列安裝軟件 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從 Linux 命令列安裝軟件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從 Linux 命令列安裝軟件 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180824 How to install software from the Linux command line","title":"如何從 Linux 命令列安裝軟件","tag":"201809","desc":""},"relativePath":"201809/20180824 How to install software from the Linux command line.md","filePath":"[post].md"}'),u={name:"201809/20180824 How to install software from the Linux command line.md"};function h(g,e,b,k,c,m){const i=p("Link");return d(),o("div",null,[e[22]||(e[22]=r(`<h1 id="如何從-linux-命令列安裝軟件" tabindex="-1">如何從 Linux 命令列安裝軟件 <a class="header-anchor" href="#如何從-linux-命令列安裝軟件" aria-label="Permalink to “如何從 Linux 命令列安裝軟件”">​</a></h1><blockquote><p>學習一種不同的包管理器和怎麼使用它。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/suitcase_container_bag.png?itok=q40lKCBY" alt=""></p><p>如果你在一直在使用 Linux，你很快就會發現做同樣的事情有很多不同的方法。這包括通過命令列在 Linux 上安裝應用。我已經是大約 25 年的 Linux 用户，我一次又一次地回到命令列來安裝我的應用。</p><p>從命令列安裝應用程序最常用的方法是使用稱為包管理器通過軟件庫（存儲軟件的地方）安裝。所有 Linux 應用都作為軟件包分發，這些軟件包只不過是與軟件包管理系統相關的文件。每個 Linux 發行版都附帶一個包管理系統，但它們並不完全相同。</p><h3 id="什麼是包管理系統" tabindex="-1">什麼是包管理系統？ <a class="header-anchor" href="#什麼是包管理系統" aria-label="Permalink to “什麼是包管理系統？”">​</a></h3><p>包管理系統由一組工具和文件格式組成，它們一起用於安裝、更新和卸載 Linux 應用。兩種最常見的包管理系統來自 Red Hat 和 Debian。 Red Hat、CentOS 和 Fedora 都使用 <code>rpm</code> 系統（.rpm 文件），而 Debian、Ubuntu、Mint 和 Ubuntu 都使用 <code>dpkg</code>（.deb 文件）。Gentoo Linux 使用名為 Portage 的系統，Arch Linux 只使用 tarball（.tar 文件）。這些系統之間的主要區別在於它們如何安裝和維護應用。</p><p>你可能想知道 <code>.rpm</code>、<code>.deb</code> 或 <code>.tar</code> 文件中的內容。你可能會驚訝地發現，所有這些都只是普通的老式歸檔文件（如 <code>.zip</code>），其中包含應用的代碼，如何安裝它的説明，依賴項（它可能依賴的其他應用），以及配置文件的位置。讀取和執行所有這些指令的軟件稱為包管理器。</p><h3 id="debian、ubuntu、mint-等" tabindex="-1">Debian、Ubuntu、Mint 等 <a class="header-anchor" href="#debian、ubuntu、mint-等" aria-label="Permalink to “Debian、Ubuntu、Mint 等”">​</a></h3><p>Debian、Ubuntu、Mint 和其它基於 Debian 的發行版都使用 <code>.deb</code> 文件和 <code>dpkg</code> 包管理系統。有兩種方法可以通過此係統安裝應用。你可以使用 <code>apt</code> 程序從倉庫進行安裝，也可以使用 <code>dpkg</code> 程序從 <code>.deb</code> 文件安裝應用。我們來看看如何做到這兩點。</p><p>使用 <code>apt</code> 安裝應用非常簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install app_name</span></span></code></pre></div><p>通過 <code>apt</code> 卸載應用也非常簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt remove app_name</span></span></code></pre></div><p>要升級已安裝的應用，首先需要更新應用倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p>完成後，你可以使用以下命令更新任何程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt upgrade</span></span></code></pre></div><p>如果你只想更新一個應用，該怎麼辦？沒問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update app_name</span></span></code></pre></div><p>最後，假設你要安裝的應用不存在於 Debian 倉庫中，但有 <code>.deb</code> 下載。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg -i app_name.deb</span></span></code></pre></div><h3 id="red-hat、centos-和-fedora" tabindex="-1">Red Hat、CentOS 和 Fedora <a class="header-anchor" href="#red-hat、centos-和-fedora" aria-label="Permalink to “Red Hat、CentOS 和 Fedora”">​</a></h3><p>默認情況下，Red Hat 使用多個包管理系統。這些系統在使用自己的命令時，互相仍然非常相似，而且與 Debian 中使用的也相似。例如，我們可以使用 <code>yum</code> 或 <code>dnf</code> 管理器來安裝應用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install app_name</span></span>
<span class="line"><span>$ sudo dnf install app_name</span></span></code></pre></div><p><code>.rpm</code> 格式的應用也可以使用 <code>rpm</code> 命令安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -i app_name.rpm</span></span></code></pre></div><p>刪除不需要的應用同樣容易。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum remove app_name</span></span>
<span class="line"><span>$ sudo dnf remove app_name</span></span></code></pre></div><p>更新應用同樣容易。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum update</span></span>
<span class="line"><span>$ sudo dnf upgrade --refresh</span></span></code></pre></div><p>如你所見，從命令列安裝、卸載和更新 Linux 應用並不難。事實上，一旦你習慣它，你會發現它比使用基於桌面 GUI 的管理工具更快！</p>`,32)),n("p",null,[e[3]||(e[3]=s("有關從命令列安裝應用程序的更多信息，請訪問 Debian ",-1)),a(i,{href:"https://wiki.debian.org/Apt"},{default:t(()=>[...e[0]||(e[0]=[s("Apt wiki",-1)])]),_:1}),e[4]||(e[4]=s("、",-1)),a(i,{href:"https://access.redhat.com/articles/yum-cheat-sheet"},{default:t(()=>[...e[1]||(e[1]=[s("Yum 速查表",-1)])]),_:1}),e[5]||(e[5]=s(" 和 ",-1)),a(i,{href:"https://fedoraproject.org/wiki/DNF?rd=Dnf"},{default:t(()=>[...e[2]||(e[2]=[s("DNF wiki",-1)])]),_:1}),e[6]||(e[6]=s("。",-1))]),e[23]||(e[23]=n("hr",null,null,-1)),n("p",null,[e[8]||(e[8]=s("via: ",-1)),a(i,{href:"https://opensource.com/article/18/8/how-install-software-linux-command-line"},{default:t(()=>[...e[7]||(e[7]=[s("https://opensource.com/article/18/8/how-install-software-linux-command-line",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=s("作者：",-1)),a(i,{href:"https://opensource.com/users/pmullins"},{default:t(()=>[...e[9]||(e[9]=[s("Patrick H.Mullins",-1)])]),_:1}),e[14]||(e[14]=s(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[10]||(e[10]=[s("lujun9972",-1)])]),_:1}),e[15]||(e[15]=s(" 譯者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[11]||(e[11]=[s("geekpi",-1)])]),_:1}),e[16]||(e[16]=s(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[12]||(e[12]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[19]||(e[19]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[17]||(e[17]=[s("LCTT",-1)])]),_:1}),e[20]||(e[20]=s(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[18]||(e[18]=[s("Linux中國",-1)])]),_:1}),e[21]||(e[21]=s(" 榮譽推出",-1))])])}const y=l(u,[["render",h]]);export{C as __pageData,y as default};
